const fs = require('node:fs')
const path = require('node:path')

test('packed Android configuration owns copied dependency bundle inputs', () => {
  const root = path.join(__dirname, '..')
  const gradle = fs.readFileSync(path.join(root, 'android/build.gradle'), 'utf8')
  expect(gradle).toContain('apply from: file("bundle-js-inputs.gradle")')
  expect(gradle).toContain('def ubmJavaScriptPackageRoot = projectDir.parentFile')
  expect(gradle).toContain('configureInstalledUbmBundleInputs(applicationProject, ubmJavaScriptPackageRoot)')
  expect(gradle).toContain('pluginManager.withPlugin("com.android.application")')
  const helper = fs.readFileSync(path.join(root, 'android/bundle-js-inputs.gradle'), 'utf8')
  expect(helper).toContain('configureEach')
  expect(helper).not.toContain('upToDateWhen')
  expect(helper).not.toContain('outputs.cacheIf')
  expect(helper).not.toContain('System.currentTimeMillis')
  const pkg = JSON.parse(fs.readFileSync(path.join(root, 'package.json'), 'utf8'))
  expect(pkg.files).toContain('android')
  expect(pkg.scripts['test:native-protocol:android']).toContain('node ../../scripts/ci/check-android-bundle-inputs.js')
  const verifier = fs.readFileSync(path.join(root, 'scripts/ci/verify-package-tarballs.js'), 'utf8')
  expect(verifier).toContain("'package/android/bundle-js-inputs.gradle'")
})
